#!/usr/bin/env python3
from __future__ import annotations

import base64
from pathlib import Path

WORKFLOW = Path('.github/workflows/dopamine-main-stable-installer.yml')

SUFFIX_B64 = ''''''


def main() -> int:
    text = WORKFLOW.read_text()
    text = text.replace('name: Dopamine main stable installer', 'name: Dopamine main Cloudflare installer', 1)
    text = text.replace('  pages: write\n', '')
    text = text.replace('  id-token: write\n', '')
    text = text.replace('  PAGES_BASE_URL: https://nightvibes33.github.io/app-code-certificates\n', '')

    old_state = '''          git fetch origin gh-pages:refs/remotes/origin/gh-pages 2>/dev/null || true
          PUBLISHED_SHA="$(git show origin/gh-pages:complete/latest/source-sha.txt 2>/dev/null | tr -d '\\r\\n' || true)"
'''
    new_state = '''          PUBLISHED_SHA="$(cat cloudflare-source-sha.txt 2>/dev/null | tr -d '\\r\\n' || true)"
'''
    if old_state not in text:
        raise SystemExit('Pages source-state block not found')
    text = text.replace(old_state, new_state, 1)

    marker = '\n  publish:\n'
    if marker not in text:
        raise SystemExit('Pages publish job not found')
    text = text.split(marker, 1)[0].rstrip() + '\n'
    suffix = base64.b64decode(SUFFIX_B64).decode()
    WORKFLOW.write_text(text + suffix)

    result = WORKFLOW.read_text()
    forbidden = ('GitHub Pages', 'gh-pages', 'deploy-pages', 'PAGES_BASE_URL')
    found = [token for token in forbidden if token in result]
    if found:
        raise SystemExit(f'Pages references remain: {found}')
    if 'trycloudflare.com' not in result:
        raise SystemExit('Cloudflare publisher missing')
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
